-- ISOLATED restored DB ONLY; simulated owner claims, no real JWT assertion.
-- The helper supplies BEGIN / ROLLBACK. No application source is replaced.
CREATE TEMP TABLE attendance_rehearsal_scope AS
SELECT p.id payroll_id,p.company_id,p.worker_id,p.period_start,p.period_end,
 p.detail,p.gross_pay,p.deductions,p.net_pay
FROM public.payroll_statements p
WHERE md5(to_jsonb(p)::text)='acdb78113fd628c32411c8ce73086213';
DO $preflight$
DECLARE s record;
BEGIN
 IF (SELECT count(*) FROM attendance_rehearsal_scope)<>1
 THEN RAISE EXCEPTION 'protected original payroll no longer matches archive'; END IF;
 SELECT * INTO s FROM attendance_rehearsal_scope;
 IF (SELECT md5(prosrc) FROM pg_proc WHERE oid='public.force_manage_attendance(text,jsonb)'::regprocedure)
 IS DISTINCT FROM '077b4a1373689071c84e0a14f0a8d824'
 THEN RAISE EXCEPTION 'management RPC baseline differs'; END IF;
 IF s.period_start<>'2026-10-01'::date OR s.period_end<>'2026-10-31'::date
 OR private.payroll_draft_source_fingerprint(s.company_id,s.worker_id,s.period_start)
 IS DISTINCT FROM '6f3b94cb97c35a04ea6db70d1ccbe17c'
 THEN RAISE EXCEPTION 'payroll source baseline differs'; END IF;
 IF EXISTS(SELECT 1 FROM public.workers WHERE id=s.worker_id AND company_id=s.company_id AND partner_company_id IS NOT NULL)
 THEN RAISE EXCEPTION 'partner payment branch not included in this scoped rehearsal'; END IF;
 IF (SELECT count(*) FROM public.company_members WHERE company_id=s.company_id AND role::text='owner')<>1
 THEN RAISE EXCEPTION 'unique existing owner required'; END IF;
 IF EXISTS(SELECT 1 FROM public.attendance_entries WHERE company_id=s.company_id AND worker_id=s.worker_id AND work_date='2026-10-13')
 OR EXISTS(SELECT 1 FROM public.paid_leave_requests WHERE company_id=s.company_id AND worker_id=s.worker_id AND leave_date='2026-10-13' AND status::text IN ('pending','approved'))
 THEN RAISE EXCEPTION 'day 13 already has attendance or leave'; END IF;
 IF (SELECT count(DISTINCT work_date) FROM public.attendance_entries WHERE company_id=s.company_id AND worker_id=s.worker_id AND work_date BETWEEN s.period_start AND s.period_end AND base_man_days>0)<>2
 THEN RAISE EXCEPTION 'expected original two attendance dates'; END IF;
END $preflight$;
CREATE TEMP TABLE attendance_rehearsal_raw AS
SELECT p.* FROM public.attendance_verifications p JOIN attendance_rehearsal_scope s
ON p.company_id=s.company_id AND p.worker_id=s.worker_id WHERE p.work_date='2026-10-13';
CREATE TEMP TABLE attendance_rehearsal_invoices AS
SELECT i.* FROM public.invoices i JOIN attendance_rehearsal_scope s ON i.company_id=s.company_id
WHERE i.billing_period_start=s.period_start AND i.billing_period_end=s.period_end
AND i.status='draft' AND i.automatic_calculation
AND EXISTS(SELECT 1 FROM jsonb_array_elements(i.snapshot->'sites') site
 WHERE (site->>'site_id')::uuid IN (SELECT site_id FROM attendance_rehearsal_raw));
CREATE TEMP TABLE attendance_rehearsal_other_invoices AS SELECT to_jsonb(i) value FROM public.invoices i
WHERE id NOT IN(SELECT id FROM attendance_rehearsal_invoices);
CREATE TEMP TABLE attendance_rehearsal_report_workers AS SELECT to_jsonb(d) value FROM public.daily_report_workers d;
CREATE TEMP TABLE attendance_rehearsal_route_history AS SELECT jsonb_build_object(
 'requests',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM private.route_billing_quantity_requests t),
 'evidence',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM private.route_billing_quantity_evidence t),
 'audit',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM private.route_billing_quantity_audit t)) value;
CREATE TEMP TABLE attendance_rehearsal_reports AS SELECT to_jsonb(d) value FROM public.daily_reports d;
CREATE TEMP TABLE attendance_rehearsal_members AS SELECT to_jsonb(d) value FROM public.communication_group_members d;
CREATE TEMP TABLE attendance_rehearsal_other_payroll AS SELECT to_jsonb(p) value FROM public.payroll_statements p
WHERE id<>(SELECT payroll_id FROM attendance_rehearsal_scope);
CREATE TEMP TABLE attendance_rehearsal_notice_before AS SELECT count(*) n FROM public.app_notifications;
CREATE TEMP TABLE attendance_rehearsal_receipt_before AS SELECT count(*) n FROM private.attendance_clock_in_notification_receipts;
DO $run_management$
DECLARE s record; incoming public.attendance_verifications; outgoing public.attendance_verifications;
 actor uuid; result integer; invoice_quantity numeric;
BEGIN
 SELECT * INTO s FROM attendance_rehearsal_scope;
 IF (SELECT count(*) FROM attendance_rehearsal_raw)<>2
 OR (SELECT count(DISTINCT site_id) FROM attendance_rehearsal_raw)<>1
 OR EXISTS(SELECT 1 FROM attendance_rehearsal_raw WHERE daily_report_id IS NOT NULL OR route_assignment_id IS NOT NULL)
 THEN RAISE EXCEPTION 'expected original single-site manual punch pair'; END IF;
 SELECT * INTO STRICT incoming FROM attendance_rehearsal_raw WHERE event_type='clock_in';
 SELECT * INTO STRICT outgoing FROM attendance_rehearsal_raw WHERE event_type='clock_out';
 IF incoming.confirmed_at>=outgoing.confirmed_at OR incoming.site_id IS NULL
 OR EXISTS(SELECT 1 FROM public.daily_reports WHERE company_id=s.company_id AND site_id=incoming.site_id AND report_date='2026-10-13')
 THEN RAISE EXCEPTION 'day 13 source changed'; END IF;
 IF (SELECT count(*) FROM attendance_rehearsal_invoices)<>1
 THEN RAISE EXCEPTION 'unique editable invoice required'; END IF;
 SELECT sum((line->>'quantity')::numeric) INTO invoice_quantity
 FROM attendance_rehearsal_invoices i CROSS JOIN LATERAL jsonb_array_elements(i.snapshot->'sites') site
 CROSS JOIN LATERAL jsonb_array_elements(site->'lines') line;
 IF invoice_quantity IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'invoice baseline quantity differs'; END IF;
 SELECT user_id INTO STRICT actor FROM public.company_members WHERE company_id=s.company_id AND role::text='owner';
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF auth.uid() IS DISTINCT FROM actor OR private.account_access_allowed() IS NOT TRUE
 THEN RAISE EXCEPTION 'isolated owner context rejected'; END IF;
 SELECT public.force_manage_attendance('upsert',jsonb_build_array(jsonb_build_object(
 'worker_id',s.worker_id,'date','2026-10-13','mode','work','site_id',incoming.site_id,
 'man_days',1,'overtime_hours',0,'early_hours',0,'night_hours',0,'allowance_names','[]'::jsonb,
 'notes','Isolated rehearsal only: user-confirmed one man-day; no production repair',
 'work_description','','clock_in',to_char(incoming.confirmed_at AT TIME ZONE 'Asia/Tokyo','HH24:MI:SS.US'),
 'clock_out',to_char(outgoing.confirmed_at AT TIME ZONE 'Asia/Tokyo','HH24:MI:SS.US')))) INTO result;
 IF result<>1 THEN RAISE EXCEPTION 'management RPC did not repair one date'; END IF;
 EXECUTE 'RESET ROLE';
END $run_management$;
DO $assert_result$
DECLARE s record; p public.payroll_statements; quantity numeric;
BEGIN
 SELECT * INTO s FROM attendance_rehearsal_scope;
 IF (SELECT count(DISTINCT work_date) FROM public.attendance_entries WHERE company_id=s.company_id AND worker_id=s.worker_id AND work_date BETWEEN s.period_start AND s.period_end AND base_man_days>0)<>3
 OR (SELECT count(*) FROM public.attendance_entries WHERE company_id=s.company_id AND worker_id=s.worker_id AND work_date='2026-10-13' AND base_man_days=1 AND site_id=(SELECT site_id FROM attendance_rehearsal_raw LIMIT 1))<>1
 THEN RAISE EXCEPTION 'repaired attendance is not three dates / one man-day'; END IF;
 SELECT * INTO STRICT p FROM public.payroll_statements WHERE id=s.payroll_id;
 IF (p.detail->>'出勤日数')::numeric IS DISTINCT FROM 3 OR p.gross_pay<=0
 OR p.deductions IS DISTINCT FROM s.deductions OR p.net_pay IS DISTINCT FROM greatest(0,p.gross_pay-p.deductions)
 THEN RAISE EXCEPTION 'payroll days / saved deductions / totals differ'; END IF;
 SELECT sum((line->>'quantity')::numeric) INTO quantity FROM public.invoices i
 JOIN attendance_rehearsal_invoices old ON old.id=i.id
 CROSS JOIN LATERAL jsonb_array_elements(i.snapshot->'sites') site
 CROSS JOIN LATERAL jsonb_array_elements(site->'lines') line;
 IF quantity IS DISTINCT FROM 3 OR EXISTS(SELECT 1 FROM public.invoices i JOIN attendance_rehearsal_invoices old ON old.id=i.id
 WHERE i.calculation_blocked OR i.grand_total<=old.grand_total
 OR i.snapshot->'expense_extra_amount_yen' IS DISTINCT FROM old.snapshot->'expense_extra_amount_yen')
 THEN RAISE EXCEPTION 'invoice does not reflect three days / preserved expense'; END IF;
 IF EXISTS(SELECT 1 FROM attendance_rehearsal_raw old WHERE NOT EXISTS(SELECT 1 FROM public.attendance_verifications n
 WHERE n.company_id=s.company_id AND n.worker_id=s.worker_id AND n.work_date='2026-10-13'
 AND n.event_type=old.event_type AND n.confirmed_at=old.confirmed_at AND n.id<>old.id))
 THEN RAISE EXCEPTION 'original timestamp precision was lost'; END IF;
 IF (SELECT jsonb_build_object(
 'requests',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM private.route_billing_quantity_requests t),
 'evidence',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM private.route_billing_quantity_evidence t),
 'audit',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]') FROM private.route_billing_quantity_audit t)))
 IS DISTINCT FROM (SELECT value FROM attendance_rehearsal_route_history)
 THEN RAISE EXCEPTION 'approved route quantity history changed'; END IF;
 IF EXISTS(SELECT 1 FROM attendance_rehearsal_other_invoices old WHERE NOT EXISTS(SELECT 1 FROM public.invoices d WHERE to_jsonb(d)=old.value))
 OR EXISTS(SELECT 1 FROM attendance_rehearsal_report_workers old WHERE NOT EXISTS(SELECT 1 FROM public.daily_report_workers d WHERE to_jsonb(d)=old.value))
 OR EXISTS(SELECT 1 FROM attendance_rehearsal_reports old WHERE NOT EXISTS(SELECT 1 FROM public.daily_reports d WHERE to_jsonb(d)=old.value))
 OR EXISTS(SELECT 1 FROM attendance_rehearsal_members old WHERE NOT EXISTS(SELECT 1 FROM public.communication_group_members d WHERE to_jsonb(d)=old.value))
 OR EXISTS(SELECT 1 FROM attendance_rehearsal_other_payroll old WHERE NOT EXISTS(SELECT 1 FROM public.payroll_statements d WHERE to_jsonb(d)=old.value))
 THEN RAISE EXCEPTION 'existing report/membership/other payroll changed'; END IF;
 IF (SELECT count(*) FROM public.app_notifications)-(SELECT n FROM attendance_rehearsal_notice_before)<>1
 OR (SELECT count(*) FROM private.attendance_clock_in_notification_receipts)-(SELECT n FROM attendance_rehearsal_receipt_before)<>1
 THEN RAISE EXCEPTION 'unexpected management notification side effects'; END IF;
END $assert_result$;

