CREATE TEMP TABLE attendance_clone_inventory(schema_name text,table_name text,row_count bigint,row_md5 text);
DO $inventory$
DECLARE t record; n bigint; h text;
BEGIN
 FOR t IN SELECT ns.nspname,cl.relname FROM pg_class cl JOIN pg_namespace ns ON ns.oid=cl.relnamespace
 WHERE cl.relkind IN ('r','p') AND ns.nspname NOT IN ('pg_catalog','information_schema')
 AND ns.nspname NOT LIKE 'pg_toast%' AND ns.nspname NOT LIKE 'pg_temp%' ORDER BY ns.nspname,cl.relname
 LOOP
  EXECUTE format('SELECT count(*),md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),''[]''::jsonb)::text) FROM %I.%I x',t.nspname,t.relname) INTO n,h;
  INSERT INTO attendance_clone_inventory VALUES(t.nspname,t.relname,n,h);
 END LOOP;
END $inventory$;
SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY schema_name,table_name),'[]'::jsonb) FROM attendance_clone_inventory x;
DROP TABLE attendance_clone_inventory;
